package com.aistock.prediction.portfolioanalysis;
import java.time.*;import java.math.*;import java.util.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import com.aistock.common.BusinessException;import com.aistock.prediction.modelcatalog.ModelRecords.Actor;import org.springframework.http.HttpStatus;
import static com.aistock.prediction.portfolioanalysis.PortfolioRecords.*;import static com.aistock.prediction.portfolioanalysis.PortfolioTestEvidence.*;
class PortfolioServiceTest {
 PortfolioRepository repo;PortfolioSources sources;PortfolioService service;UUID request,generation;Operation running,done;SessionToken token=new SessionToken("a".repeat(43));Actor actor=new Actor(OWNER,"USER");QuoteBatch batch;
 @BeforeEach void setup(){repo=mock(PortfolioRepository.class);sources=mock(PortfolioSources.class);request=UUID.randomUUID();generation=UUID.randomUUID();running=new Operation(request,"RUNNING",null,null,NOW,NOW.plusSeconds(30));done=new Operation(request,"SUCCEEDED",UUID.randomUUID(),null,NOW,NOW.plusSeconds(30));batch=new QuoteBatch(LocalDate.parse("2026-09-28"),NOW,prices().items());when(repo.claim(eq(OWNER),eq(request),any(),any(),any())).thenReturn(new Claim(true,generation,running,false));when(sources.snapshot(token)).thenReturn(normal());when(sources.quotes(anyList(),any())).thenReturn(batch);when(sources.revision(token)).thenReturn(new PositionRevision(OWNER,"stock-user-service","2"));when(repo.complete(eq(OWNER),eq(request),eq(generation),any(),any(),any(),any())).thenReturn(done);service=new PortfolioService(repo,sources,Clock.fixed(NOW,ZoneOffset.UTC),new BigDecimal("50"),1);}
 @Test void successRechecksOriginalSessionAndReadsNeverRefreshSources(){assertEquals("SUCCEEDED",service.create(actor,token,new Request(request)).operation().state());var order=inOrder(repo,sources);order.verify(repo).claim(eq(OWNER),eq(request),any(),any(),any());order.verify(sources).snapshot(token);order.verify(sources).quotes(anyList(),any());order.verify(sources).revision(token);order.verify(repo).complete(eq(OWNER),eq(request),eq(generation),any(),any(),any(),any());service.get(actor,done.analysisId());service.list(actor,null,null);verify(sources,times(1)).quotes(anyList(),any());}
 @Test void mismatchedOwnerFailsBeforeReadingPrices(){when(sources.snapshot(token)).thenReturn(new PositionSnapshot(UUID.randomUUID(),"stock-user-service","2",normal().items()));var e=assertThrows(BusinessException.class,()->service.create(actor,token,new Request(request)));assertEquals("PORTFOLIO_SOURCE_INVALID",e.code());verify(sources,never()).quotes(anyList(),any());verify(repo,never()).complete(any(),any(),any(),any(),any(),any(),any());}
 @Test void changedBookCannotSaveMixedInputs(){when(sources.revision(token)).thenReturn(new PositionRevision(OWNER,"stock-user-service","3"));var e=assertThrows(BusinessException.class,()->service.create(actor,token,new Request(request)));assertEquals("PORTFOLIO_CHANGED",e.code());verify(repo).fail(eq(OWNER),eq(request),eq(generation),eq("PORTFOLIO_CHANGED"),any());verify(repo,never()).complete(any(),any(),any(),any(),any(),any(),any());}
 @Test void revokedSessionAfterQuotesPreservesUnauthorizedAndOldResults(){when(sources.revision(token)).thenThrow(new BusinessException("AUTH_REQUIRED","fixture",HttpStatus.UNAUTHORIZED));var e=assertThrows(BusinessException.class,()->service.create(actor,token,new Request(request)));assertEquals(401,e.status().value());verify(repo,never()).complete(any(),any(),any(),any(),any(),any(),any());service.get(actor,done.analysisId());verify(repo).get(OWNER,done.analysisId());}
 @Test void replaysOnlyReadOriginalOperationWithoutNewSources(){when(repo.find(OWNER,request,NOW)).thenReturn(done);var replay=service.create(actor,token,new Request(request));assertTrue(replay.replayed());assertEquals(done,replay.operation());verifyNoInteractions(sources);verify(repo,never()).claim(any(),any(),any(),any(),any());}
 @Test void busyRejectsBeforeCreatingAdditionalOperationButReplayBypassesGate()throws Exception{var entered=new CountDownLatch(1);var release=new CountDownLatch(1);when(sources.snapshot(token)).thenAnswer(c->{entered.countDown();if(!release.await(3,TimeUnit.SECONDS))throw new IllegalStateException();return normal();});var executor=Executors.newSingleThreadExecutor();try{var first=executor.submit(()->service.create(actor,token,new Request(request)));assertTrue(entered.await(2,TimeUnit.SECONDS));var second=UUID.randomUUID();assertEquals("PORTFOLIO_BUSY",assertThrows(BusinessException.class,()->service.create(actor,token,new Request(second))).code());verify(repo,never()).claim(eq(OWNER),eq(second),any(),any(),any());when(repo.find(OWNER,second,NOW)).thenReturn(done);assertTrue(service.create(actor,token,new Request(second)).replayed());release.countDown();assertEquals("SUCCEEDED",first.get(3,TimeUnit.SECONDS).operation().state());}finally{release.countDown();executor.shutdownNow();}}
 @Test void emptyBookRequiresNoMarketCallButStillChecksRevision(){when(sources.snapshot(token)).thenReturn(snapshot());service.create(actor,token,new Request(request));verify(sources,never()).quotes(anyList(),any());verify(sources).revision(token);verify(repo).complete(eq(OWNER),eq(request),eq(generation),argThat(c->"EMPTY".equals(c.state())),any(),any(),any());}
 @Test void malformedOwnedSnapshotIsRejectedBeforeRequestingQuotes(){when(sources.snapshot(token)).thenReturn(snapshot(position("SH600030","1","1e2")));assertEquals("PORTFOLIO_SOURCE_INVALID",assertThrows(BusinessException.class,()->service.create(actor,token,new Request(request))).code());verify(sources,never()).quotes(anyList(),any());}
 @Test void deadlineAfterQuotesPreventsRevisionAndSaving(){var current=new java.util.concurrent.atomic.AtomicReference<>(NOW);Clock clock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return current.get();}};when(sources.quotes(anyList(),any())).thenAnswer(c->{current.set(NOW.plusSeconds(31));return batch;});var timed=new PortfolioService(repo,sources,clock,new BigDecimal("50"),1);assertEquals("PORTFOLIO_OPERATION_EXPIRED",assertThrows(BusinessException.class,()->timed.create(actor,token,new Request(request))).code());verify(sources,never()).revision(any());verify(repo,never()).complete(any(),any(),any(),any(),any(),any(),any());}
}
